<div class="page-heading"><div><p class="eyebrow">Administration</p><h1>System reports</h1><p>Cash sales use pickup/completion date; order outcomes use the date the order was placed.</p></div></div>
<form class="filter-bar report-filter" method="get" action="<?= h(app_url('admin.reports')) ?>"><input type="hidden" name="r" value="admin.reports"><div class="form-field"><label for="start">From</label><input id="start" type="date" name="start" value="<?= h($start) ?>" required></div><div class="form-field"><label for="end">To</label><input id="end" type="date" name="end" value="<?= h($end) ?>" required></div><button class="button" type="submit">Apply dates</button></form>
<div class="kpi-grid" style="margin-top:15px"><div class="kpi"><span class="kpi-label">Completed sales</span><strong class="kpi-value"><?= h(money($summary['sales']??0)) ?></strong><span class="kpi-note">By pickup/completion date</span></div><div class="kpi"><span class="kpi-label">Orders placed</span><strong class="kpi-value"><?= (int)($summary['order_count']??0) ?></strong><span class="kpi-note">By order date</span></div><div class="kpi"><span class="kpi-label">Completed</span><strong class="kpi-value"><?= (int)($summary['completed_count']??0) ?></strong><span class="kpi-note">Cash paid in range</span></div><div class="kpi"><span class="kpi-label">Cancelled / rejected</span><strong class="kpi-value"><?= (int)($summary['cancelled_count']??0) ?> / <?= (int)($summary['rejected_count']??0) ?></strong><span class="kpi-note">Order outcomes</span></div></div>
<div class="dashboard-grid"><section class="panel"><h2 class="panel-title">Daily cash sales</h2><?php if ($daily): ?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Sales</th><th>Transactions</th></tr></thead><tbody><?php foreach ($daily as $row): ?><tr><td><?= h(format_datetime($row['day'],'D, M j')) ?></td><td><?= h(money($row['sales'])) ?></td><td><?= (int)$row['transactions'] ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">No completed sales in this period.</p><?php endif; ?></section>
<section class="panel"><h2 class="panel-title">Vendor activity</h2><?php if ($vendors): ?><div class="table-wrap"><table><thead><tr><th>Vendor</th><th>Orders</th><th>Sales</th></tr></thead><tbody><?php foreach ($vendors as $vendor): ?><tr><td><?= h($vendor['name']) ?></td><td><?= (int)$vendor['completed_orders'] ?></td><td><?= h(money($vendor['sales'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="muted">No vendor data for this period.</p><?php endif; ?></section></div>
